    for r in range(H):
        t=max((c for c,v in enumerate(a[r]) if v!=bg), default=-1)
        tip[r]=t
    rows_with=[r for r in range(H) if tip[r]>=0]
    # map each row to a band id
    band_of={}
    for bi,b in enumerate(bs):
        for r in b: band_of[r]=bi
    for r in rows_with:
        refs=[j for j in rows_with if band_of[j]!=band_of[r]]
        if mode=='below': refs=[j for j in refs if band_of[j]>band_of[r]]
        elif mode=='above': refs=[j for j in refs if band_of[j]<band_of[r]]
        if not refs: continue
        B=body(a,r,bg); t=tip[r]
        for c in range(t+1,W):
            filled=False
            for j in refs:
                Bj=body(a,j,bg)
                best_s=max(srange,key=lambda s: len(B & {x+s for x in Bj}))
                # require decent overlap
                ov=len(B & {x+best_s for x in Bj})
                if ov>=max(2,len(B)//2) and (c+best_s) in Bj:
                    filled=True;break
            if filled: out[r][c]=1
    return out

