def ov(B,Bj,s):
    # match c in B with c+s in Bj  <=> c in Bj - s
    return len(B & {x-s for x in Bj})

def simulate3(a, gshift=True, minov_frac=0.5, minov_abs=2, extend_edge=False):
    H=len(a);W=len(a[0])
    bg=Counter(v for row in a for v in row).most_common(1)[0][0]
    out=[r[:] for r in a]
    bs=bands(a,bg)
    tip={}
    for r in range(H):
        tip[r]=max((c for c,v in enumerate(a[r]) if v!=bg), default=-1)
    band_of={}
    for bi,b in enumerate(bs):
        for r in b: band_of[r]=bi
    B={r:body(a,r,bg) for r in range(H) if tip[r]>=0}
    rows_with=sorted(B)
    # global shift per band pair (band j relative to band i): s aligning Bi to Bj
    gs={}
    if gshift:
        for i in range(len(bs)):
            for j in range(len(bs)):
                if i==j: continue
                best=None
                for s in range(-4,5):
                    tot=0
                    for k in range(min(len(bs[i]),len(bs[j]))):
                        r1,r2=bs[i][k],bs[j][k]
                        if r1 in B and r2 in B: tot+=ov(B[r1],B[r2],s)
                    if best is None or tot>best[1]: best=(s,tot)
                gs[(i,j)]=best[0]
    for r in rows_with:
        bi=band_of[r]
        refs=[j for j in rows_with if band_of[j]!=bi and k_ok(j,bs,bi)]
        for j in refs:
            s = gs[(bi,band_of[j])] if gshift else max(range(-4,5), key=lambda s: ov(B[r],B[j],s))
            if ov(B[r],B[j],s) < max(minov_abs, minov_frac*len(B[r])): continue
            for c in range(tip[r]+1,W):
                if (c+s) in B[j]:
                    out[r][c]=1
                    if extend_edge:
                        for cc in range(c,W): out[r][cc]=1
                    break
    return out

