def periodic_wave_fill(grid, fill=1):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    marker = next(c for c in {v for row in grid for v in row} if c != bg)
    pts = {(i, j) for i in range(h) for j in range(w) if grid[i][j] == marker}
    best = None
    for T in range(1, h):
        for s in range(-w, w + 1):
            good = bad = 0
            for (i, j) in pts:
                i2, j2 = i - T, j - s
                if 0 <= i2 < h and 0 <= j2 < w:
                    if (i2, j2) in pts: good += 1
                    else: bad += 1
            if good == 0: continue
            score = good - 3 * bad
            if best is None or score > best[0]:
                best = (score, T, s)
    score, T, s = best
    out = [row[:] for row in grid]
    n = 0
    for i in range(h):
        for j in range(w):
            if grid[i][j] != bg: continue
            for (i2, j2) in ((i - T, j - s), (i + T, j + s)):
                if 0 <= i2 < h and 0 <= j2 < w and (i2, j2) in pts:
                    out[i][j] = fill; n += 1; break
    return out, (T, s), n

