def periodic_iter(grid, fill=1):
    from collections import Counter
    bg = Counter(v for r in grid for v in r).most_common(1)[0][0]
    marker = next(c for c in {v for r in grid for v in r} if c != bg)
    h,w=len(grid),len(grid[0])
    best=None
    M={(i,j) for i in range(h) for j in range(w) if grid[i][j]==marker}
    for T in range(1,h):
        for s in range(-w+1,w):
            good=bad=0
            for (i,j) in M:
                i2,j2=i-T,j-s
                if 0<=i2<h and 0<=j2<w:
                    if (i2,j2) in M: good+=1
                    else: bad+=1
            if good and (best is None or good-3*bad>best[0]):
                best=(good-3*bad,T,s)
    if best is None: return [r[:] for r in grid]
    _,T,s=best
    out=[r[:] for r in grid]
    changed=True
    while changed:
        changed=False
        P={(i,j) for i in range(h) for j in range(w) if out[i][j]==marker}
        for i in range(h):
            for j in range(w):
                if out[i][j]!=bg: continue
                for (i2,j2) in ((i-T,j-s),(i+T,j+s)):
                    if 0<=i2<h and 0<=j2<w and (i2,j2) in P:
                        out[i][j]=fill; changed=True; break
    return out
